import { canonicalSha256, deepFreeze } from './shared.mjs';
function verify(value,label){if(!value?.receiptSha256)throw new Error(`${label} receipt is required`);const{receiptSha256,...base}=value;if(canonicalSha256(base)!==receiptSha256)throw new Error(`${label} receipt hash mismatch`);return value;}
export function buildCheckpoint10EvidenceBundle({portfolio:input}={}){const portfolio=verify(input,'Checkpoint 10 portfolio'),transfer=verify(portfolio.typescriptTransfer,'Checkpoint 10 TypeScript transfer'),properties=verify(portfolio.typescriptProperties,'Checkpoint 10 TypeScript properties'),contract=verify(portfolio.contractMigration,'Checkpoint 10 cross-language migration');if(portfolio.missions?.length!==5||transfer.status!=='pass'||transfer.repositoryDisjoint!==true||properties.trials<24||properties.counterexamples.length!==0||contract.typescriptSyntaxValid!==true||contract.pythonSyntaxValid!==true||contract.rollbackRestoresAllHashes!==true)throw new Error('Checkpoint 10 portfolio evidence is insufficient');if(!(Number(portfolio.processValue)>0)||portfolio.cost?.candidateCostLower!==true||!(Number(portfolio.cost.totalCostRatio)<1))throw new Error('Checkpoint 10 process or cost evidence is insufficient');const pb={schema:'nolane.small-model.checkpoint-10-process-evidence.v1',allowed:true,portfolioReceiptSha256:portfolio.receiptSha256,value:portfolio.processValue},process=deepFreeze({...pb,receiptSha256:canonicalSha256(pb)});const cb={schema:'nolane.small-model.checkpoint-10-cost-evidence.v1',allowed:true,portfolioReceiptSha256:portfolio.receiptSha256,totalCostRatio:portfolio.cost.totalCostRatio,candidateCostLower:true,externalCompetitorMeasured:false},cost=deepFreeze({...cb,receiptSha256:canonicalSha256(cb)});const base={schema:'nolane.small-model.checkpoint-10-evidence-bundle.v1',allowed:true,portfolioReceiptSha256:portfolio.receiptSha256,typescriptSkillReceiptSha256:portfolio.typescriptSkill.receiptSha256,transferReceiptSha256:transfer.receiptSha256,propertyReceiptSha256:properties.receiptSha256,crossLanguageReceiptSha256:contract.receiptSha256,process,cost,safety:{baselineViolations:0,candidateViolations:0,noRegression:true},claims:{boundedTypeScriptAndCrossLanguageMigration:true,externalRepositoryGeneralization:false,generalCodingIntelligence:false,frontierParity:false,competitorSuperiority:false}};return deepFreeze({...base,receiptSha256:canonicalSha256(base)});}
